package tz.go.bukobamc.meetings.api;

import org.apache.commons.csv.*; import org.apache.poi.ss.usermodel.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import org.springframework.web.server.ResponseStatusException;
import tz.go.bukobamc.meetings.model.*; import tz.go.bukobamc.meetings.repo.*; import tz.go.bukobamc.meetings.security.SessionService;
import tz.go.bukobamc.meetings.service.AuditService; import tz.go.bukobamc.meetings.service.NotificationService;
import java.io.*; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.*; import java.time.format.DateTimeFormatter; import java.util.*;

@RestController @RequestMapping("/api")
public class MeetingController {
 private static final List<String> IMPORT_HEADERS=List.of("name","phone","email","role_title","organization");
 private final UserRepository users; private final MeetingRepository meetings; private final GuestRepository guests; private final InvitationRepository invitations; private final OTPVerificationRepository otps; private final QRSessionRepository qrSessions; private final AttendanceRecordRepository attendance; private final AuditLogEntryRepository auditEntries; private final SessionService sessions; private final NotificationService notifications; private final AuditService audit; private final String baseUrl; private final String defaultWhatsappSender; private final String defaultEmailSender; private final boolean whatsappEnabled; private final String appEnv; private final int qrRotationSeconds;
 public MeetingController(UserRepository u,MeetingRepository m,GuestRepository g,InvitationRepository i,OTPVerificationRepository o,QRSessionRepository q,AttendanceRecordRepository a,AuditLogEntryRepository al,SessionService s,NotificationService n,AuditService audits,@Value("${bmc.public-base-url}")String b,@Value("${bmc.default-whatsapp-sender}")String sender,@Value("${bmc.default-email-sender}")String email,@Value("${bmc.whatsapp-enabled:false}")boolean enabled,@Value("${APP_ENV:development}")String env,@Value("${bmc.qr-rotation-seconds:45}")int rotation){users=u;meetings=m;guests=g;invitations=i;otps=o;qrSessions=q;attendance=a;auditEntries=al;sessions=s;notifications=n;audit=audits;baseUrl=b;defaultWhatsappSender=sender;defaultEmailSender=email;whatsappEnabled=enabled;appEnv=env;qrRotationSeconds=rotation;}
 private User auth(String h){return sessions.require(h);}
 private static String hash(String x){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(x.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private static boolean past(Meeting m){return m.endAt!=null&&!m.endAt.isAfter(OffsetDateTime.now());}
 private static void ensureEditable(Meeting m){if(past(m))throw new ResponseStatusException(HttpStatus.CONFLICT,"Past meetings are read-only");if("cancelled".equals(m.status))throw new ResponseStatusException(HttpStatus.CONFLICT,"Cancelled meetings are read-only");}
 private Meeting readable(User u,Long id){Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));if(!"admin".equals(u.role)&&!Objects.equals(m.createdBy,u.id))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found");return m;}
 private Meeting writable(User u,Long id){Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));if(!"admin".equals(u.role)&&!Objects.equals(m.createdBy,u.id))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the organiser or an administrator may change this meeting");ensureEditable(m);return m;}
 private void cleanupPending(){for(User u:users.findByStatusAndCreatedAtBefore("pending",OffsetDateTime.now().minusHours(24))){otps.deleteByUserId(u.id);users.delete(u);}}
 private String issueOtp(User u,String channel){if(!channel.equals("email")&&!channel.equals("phone"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Channel must be email or phone");String alphabet="ABCDEFGHJKLMNPQRSTUVWXYZ23456789";StringBuilder generated=new StringBuilder(6);SecureRandom random=new SecureRandom();for(int i=0;i<6;i++)generated.append(alphabet.charAt(random.nextInt(alphabet.length())));String code=generated.toString();OTPVerification v=otps.findTopByUserIdAndChannelAndUsedFalseOrderByIdDesc(u.id,channel).orElseGet(OTPVerification::new);v.user=u;v.channel=channel;v.codeHash=hash(code);v.expiresAt=OffsetDateTime.now().plusMinutes(10);v.attemptCount=0;v.used=false;v.resendCount++;v.lastSentAt=OffsetDateTime.now();otps.save(v);String message="Your BMC-MMS "+channel+" OTP is "+code+". It expires in 10 minutes and can be used once.";if(channel.equals("email")){if("development".equalsIgnoreCase(appEnv))System.out.println("[DEV OTP] email="+u.email+" code="+code);notifications.email(u.email,"BMC-MMS verification code",message);}else notifications.whatsapp(u.phone,message);return code;}
 private static String newToken(){return Base64.getUrlEncoder().withoutPadding().encodeToString(UUID.randomUUID().toString().getBytes(StandardCharsets.UTF_8));}
 @GetMapping("/health") public Map<String,String> health(){return Map.of("status","ok","service","bmc-meetings-springboot");}
 public record Login(String email,String password){} public record Register(String name,String email,String phone,String password){} public record Verify(String email,String channel,String code){} public record Resend(String email,String channel){} public record ProfileIn(String name,String phone){} public record MeetingIn(String title,String purpose,OffsetDateTime start_at,OffsetDateTime end_at,String location,String map_link,String virtual_link,String department,String meeting_type,String priority,String status){} public record GuestIn(String name,String phone,String email,String role_title,String organization){} public record RsvpIn(String status,String reason,String language){} public record AttendanceIn(String personal_token,String qr_payload){} public record CancelIn(String reason){}
 @PostMapping("/auth/register") public Object register(@RequestBody Register x){cleanupPending();String email=x.email().trim().toLowerCase(),phone=x.phone().trim();if(users.findByEmail(email).filter(u->u.active||!"pending".equals(u.status)).isPresent()||users.findByPhone(phone).filter(u->u.active||!"pending".equals(u.status)).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email or phone is already verified by another account");User u=users.findByEmail(email).orElseGet(User::new);u.name=x.name();u.email=email;u.phone=phone;u.passwordHash=hash(x.password());u.role="organizer";u.status="pending";u.active=false;u.emailVerified=false;u.phoneVerified=!whatsappEnabled;u=users.save(u);String emailCode=issueOtp(u,"email");if(whatsappEnabled)issueOtp(u,"phone");audit.record(u.id,"register","User",u.id,"Pending organiser registration for "+email);Map<String,Object> result=new LinkedHashMap<>();result.put("status","pending");result.put("message",whatsappEnabled?"Enter the Email OTP and WhatsApp OTP sent to your contacts":"Enter the Email OTP sent to your email address");if("development".equalsIgnoreCase(appEnv))result.put("development_email_otp",emailCode);return result;}
 @PostMapping("/auth/verify") public Object verify(@RequestBody Verify x){User u=users.findByEmail(x.email().trim().toLowerCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Registration not found"));if(!"pending".equals(u.status))return Map.of("status","active");if("phone".equals(x.channel())&&!whatsappEnabled)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"WhatsApp verification is disabled for now; verify email only");OTPVerification v=otps.findTopByUserIdAndChannelAndUsedFalseOrderByIdDesc(u.id,x.channel()).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"No active OTP for this channel"));if(v.expiresAt.isBefore(OffsetDateTime.now()))throw new ResponseStatusException(HttpStatus.GONE,"OTP expired; request a new code");if(++v.attemptCount>5||!hash(x.code()).equals(v.codeHash)){otps.save(v);throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid OTP");}v.used=true;otps.save(v);if("email".equals(x.channel()))u.emailVerified=true;else if("phone".equals(x.channel()))u.phoneVerified=true;else throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Channel must be email or phone");if(u.emailVerified&&(u.phoneVerified||!whatsappEnabled)){u.status="active";u.active=true;}users.save(u);audit.record(u.id,"verify","User",u.id,x.channel()+" verified; account status "+u.status);return Map.of("status",u.status,"verified",x.channel());}
 @PostMapping("/auth/resend") public Object resend(@RequestBody Resend x){User u=users.findByEmail(x.email().trim().toLowerCase()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Registration not found"));if(!"email".equals(x.channel())&&!"phone".equals(x.channel()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Channel must be email or phone");if("phone".equals(x.channel())&&!whatsappEnabled)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"WhatsApp verification is disabled for now; verify email only");OTPVerification old=otps.findTopByUserIdAndChannelAndUsedFalseOrderByIdDesc(u.id,x.channel()).orElse(null);if(old!=null&&old.lastSentAt!=null&&old.lastSentAt.plusSeconds(60).isAfter(OffsetDateTime.now()))throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Wait 60 seconds before resending");if(old!=null&&old.resendCount>=5&&old.lastSentAt.plusMinutes(30).isAfter(OffsetDateTime.now()))throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Resend limit reached; try again later");String code=issueOtp(u,x.channel());Map<String,Object> result=new LinkedHashMap<>();result.put("status","sent");result.put("channel",x.channel());if("development".equalsIgnoreCase(appEnv)&&"email".equals(x.channel()))result.put("development_email_otp",code);return result;}
 @PostMapping("/auth/login") public Object login(@RequestBody Login x){return users.findByEmail(x.email().trim().toLowerCase()).filter(u->hash(x.password()).equals(u.passwordHash)&&u.active&&"active".equals(u.status)).map(u->{audit.record(u.id,"login","User",u.id,"Password sign-in");return Map.of("access_token",sessions.create(u),"user",Map.of("name",u.name,"role",u.role,"email",u.email));}).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email, password, or unverified account"));}
 @GetMapping("/me") public Object me(@RequestHeader("Authorization")String h){User u=auth(h);return Map.of("name",u.name,"role",u.role,"email",u.email,"phone",Objects.toString(u.phone,""));}
 @PutMapping("/me") public Object updateProfile(@RequestHeader("Authorization")String h,@RequestBody ProfileIn x){User u=auth(h);if(x.name()!=null&&!x.name().isBlank())u.name=x.name();if(x.phone()!=null&&!x.phone().isBlank())u.phone=x.phone();users.save(u);audit.record(u.id,"update_profile","User",u.id,"Organiser profile updated");return Map.of("name",u.name,"phone",Objects.toString(u.phone,""));}
 @GetMapping("/meetings") public Object list(@RequestHeader("Authorization")String h){User u=auth(h);return meetings.findAll().stream().filter(m->"admin".equals(u.role)||Objects.equals(m.createdBy,u.id)).map(m->{Map<String,Object> x=new LinkedHashMap<>();x.put("id",m.id);x.put("reference",m.reference);x.put("title",m.title);x.put("start_at",m.startAt);x.put("end_at",m.endAt);x.put("location",Objects.toString(m.location,""));x.put("status",m.status);x.put("past",past(m));x.put("guest_count",guests.countByMeetingId(m.id));return x;}).toList();}
 @PostMapping("/meetings") public Object create(@RequestHeader("Authorization")String h,@RequestBody MeetingIn x){User u=auth(h);if(x.title()==null||x.title().isBlank())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Meeting title is required");if(x.start_at()==null||x.end_at()==null)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Meeting start and end date are required");if(x.start_at().isBefore(OffsetDateTime.now()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Meeting start must be in the future");if(!x.end_at().isAfter(x.start_at()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Meeting end must be later than the start time");Meeting m=new Meeting();m.reference="BMC-"+LocalDate.now()+"-"+UUID.randomUUID().toString().substring(0,4).toUpperCase();m.createdBy=u.id;m.title=x.title();m.purpose=x.purpose();m.startAt=x.start_at();m.endAt=x.end_at();m.location=x.location();m.mapLink=x.map_link();m.virtualLink=x.virtual_link();m.department=x.department();m.meetingType=x.meeting_type()==null?"internal":x.meeting_type();m.priority=x.priority()==null?"normal":x.priority();m.status=x.status()==null?"draft":x.status();m=meetings.save(m);audit.record(u.id,"create_meeting","Meeting",m.id,"Created "+m.reference+" with status "+m.status);return Map.of("id",m.id,"reference",m.reference);}
 @PutMapping("/meetings/{id}") public Object update(@RequestHeader("Authorization")String h,@PathVariable Long id,@RequestBody MeetingIn x){User u=auth(h);Meeting m=writable(u,id);if(x.title()==null||x.title().isBlank())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Meeting title is required");if(x.start_at()==null||x.end_at()==null||!x.end_at().isAfter(x.start_at()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"End time must be after start time");boolean rescheduled=!Objects.equals(m.startAt,x.start_at())||!Objects.equals(m.endAt,x.end_at());OffsetDateTime previousStart=m.startAt;m.title=x.title();m.purpose=x.purpose();m.startAt=x.start_at();m.endAt=x.end_at();m.location=x.location();m.mapLink=x.map_link();m.virtualLink=x.virtual_link();m.department=x.department();if(x.meeting_type()!=null)m.meetingType=x.meeting_type();if(x.priority()!=null)m.priority=x.priority();if(x.status()!=null&&!"cancelled".equals(x.status()))m.status=x.status();meetings.save(m);List<Invitation> issued=invitations.findByMeetingId(id);if(rescheduled&&!issued.isEmpty())notifyInvitees(m,issued,"BMC-MMS meeting rescheduled: "+m.title,"The meeting "+m.title+" moved from "+previousStart+" to "+m.startAt+". Location: "+Objects.toString(m.location,""));audit.record(u.id,rescheduled?"reschedule_meeting":"update_meeting","Meeting",m.id,(rescheduled?"Rescheduled from "+previousStart+" to "+m.startAt:"Details updated")+"; invitees notified: "+(rescheduled?issued.size():0));return detail(h,id);}
 @PostMapping("/meetings/{id}/cancel") public Object cancel(@RequestHeader("Authorization")String h,@PathVariable Long id,@RequestBody(required=false) CancelIn x){User u=auth(h);Meeting m=writable(u,id);String reason=x==null||x.reason()==null?"":x.reason().trim();m.status="cancelled";meetings.save(m);List<Invitation> issued=invitations.findByMeetingId(id);notifyInvitees(m,issued,"BMC-MMS meeting cancelled: "+m.title,"The meeting "+m.title+" scheduled for "+m.startAt+" is cancelled."+(reason.isBlank()?"":" Reason: "+reason));audit.record(u.id,"cancel_meeting","Meeting",m.id,"Cancelled "+m.reference+"; invitees notified: "+issued.size()+(reason.isBlank()?"":"; reason: "+reason));return Map.of("status","cancelled","notified",issued.size());}
 private void notifyInvitees(Meeting m,List<Invitation> issued,String subject,String body){for(Invitation i:issued){if(i.guest.phone!=null&&!i.guest.phone.isBlank())notifications.whatsapp(i.guest.phone,body);else notifications.email(i.guest.email,subject,body);}}
 @GetMapping("/meetings/{id}") public Object detail(@RequestHeader("Authorization")String h,@PathVariable Long id){User u=auth(h);Meeting m=readable(u,id);List<Map<String,Object>> gs=new ArrayList<>();Map<String,Integer> counts=new HashMap<>(Map.of("confirmed",0,"declined",0,"tentative",0,"no_response",0,"attended",0));List<Invitation> issued=invitations.findByMeetingId(id);Set<Long> attended=new HashSet<>();for(AttendanceRecord a:attendance.findByMeetingId(id))if(a.used)attended.add(a.participantId);for(Guest g:guests.findByMeetingId(id)){Invitation in=issued.stream().filter(i->Objects.equals(i.guest.id,g.id)).findFirst().orElse(null);String st=in!=null&&in.response!=null?in.response.status:"no_response";counts.put(st,counts.getOrDefault(st,0)+1);if(attended.contains(g.id))counts.put("attended",counts.get("attended")+1);Map<String,Object> row=new LinkedHashMap<>();row.put("id",g.id);row.put("name",g.name);row.put("phone",Objects.toString(g.phone,""));row.put("email",Objects.toString(g.email,""));row.put("organization",Objects.toString(g.organization,""));row.put("role_title",Objects.toString(g.roleTitle,""));row.put("status",st);row.put("reason",in!=null&&in.response!=null?Objects.toString(in.response.reason,""):"");row.put("delivery_status",in==null?"not_invited":Objects.toString(in.deliveryStatus,""));row.put("channel",in==null?"":Objects.toString(in.channel,""));row.put("attended",attended.contains(g.id));gs.add(row);}Map<String,Object> result=new LinkedHashMap<>();result.put("id",m.id);result.put("reference",m.reference);result.put("title",m.title);result.put("purpose",Objects.toString(m.purpose,""));result.put("start_at",m.startAt);result.put("end_at",m.endAt);result.put("location",Objects.toString(m.location,""));result.put("map_link",Objects.toString(m.mapLink,""));result.put("virtual_link",Objects.toString(m.virtualLink,""));result.put("department",Objects.toString(m.department,""));result.put("meeting_type",m.meetingType);result.put("priority",m.priority);result.put("status",m.status);result.put("invited",issued.size());result.put("counts",counts);result.put("guests",gs);return result;}
 @PostMapping("/meetings/{id}/guests") public Object addGuest(@RequestHeader("Authorization")String h,@PathVariable Long id,@RequestBody GuestIn x){User u=auth(h);Meeting m=writable(u,id);if(x.name()==null||x.name().isBlank())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Guest name is required");if((x.phone()==null||x.phone().isBlank())&&(x.email()==null||x.email().isBlank()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Phone or email is required");if(duplicate(guests.findByMeetingId(id),x.phone(),x.email()))throw new ResponseStatusException(HttpStatus.CONFLICT,"This phone number or email is already on the guest list");Guest g=new Guest();g.meeting=m;g.name=x.name();g.phone=x.phone();g.email=x.email();g.roleTitle=x.role_title();g.organization=x.organization();g=guests.save(g);audit.record(u.id,"add_guest","Guest",g.id,"Added "+g.name+" to "+m.reference);return Map.of("id",g.id);}
 private static boolean duplicate(List<Guest> existing,String phone,String email){String p=Objects.toString(phone,"").trim(),e=Objects.toString(email,"").trim().toLowerCase();for(Guest g:existing){if(!p.isBlank()&&p.equals(Objects.toString(g.phone,"").trim()))return true;if(!e.isBlank()&&e.equals(Objects.toString(g.email,"").trim().toLowerCase()))return true;}return false;}
 @PostMapping("/meetings/{id}/guests/import") public Object importGuests(@RequestHeader("Authorization")String h,@PathVariable Long id,@RequestParam MultipartFile file)throws IOException{User u=auth(h);Meeting m=writable(u,id);String filename=Objects.toString(file.getOriginalFilename(),"").toLowerCase();List<Map<String,String>> rows=filename.endsWith(".xlsx")||filename.endsWith(".xls")?readWorkbook(file):readCsv(file);int added=0,row=1;List<Map<String,Object>> skipped=new ArrayList<>();List<Guest> existing=new ArrayList<>(guests.findByMeetingId(id));for(Map<String,String> r:rows){row++;String name=r.get("name"),phone=r.get("phone"),email=r.get("email");if(name==null||name.isBlank()||((phone==null||phone.isBlank())&&(email==null||email.isBlank()))){skipped.add(Map.of("row",row,"reason","name and phone or email required"));continue;}if(email!=null&&!email.isBlank()&&!email.contains("@")){skipped.add(Map.of("row",row,"reason","invalid email address"));continue;}if(duplicate(existing,phone,email)){skipped.add(Map.of("row",row,"reason","duplicate phone or email"));continue;}Guest g=new Guest();g.meeting=m;g.name=name;g.phone=phone;g.email=email;g.roleTitle=r.get("role_title");g.organization=r.get("organization");existing.add(guests.save(g));added++;}audit.record(u.id,"import_guests","Meeting",m.id,"Imported "+added+" guest(s) into "+m.reference+", skipped "+skipped.size());return Map.of("added",added,"skipped",skipped);}
 private static List<Map<String,String>> readCsv(MultipartFile file)throws IOException{try(CSVParser p=CSVParser.parse(new InputStreamReader(file.getInputStream(),StandardCharsets.UTF_8),CSVFormat.DEFAULT.builder().setHeader().setSkipHeaderRecord(true).setIgnoreHeaderCase(true).setTrim(true).build())){requireHeaders(p.getHeaderMap().keySet());List<Map<String,String>> rows=new ArrayList<>();for(CSVRecord r:p){Map<String,String> row=new LinkedHashMap<>();for(String header:IMPORT_HEADERS)row.put(header,r.isMapped(header)?r.get(header):"");rows.add(row);}return rows;}catch(IllegalArgumentException e){throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"The file could not be read. Use the supplied guest list template.");}}
 private static List<Map<String,String>> readWorkbook(MultipartFile file)throws IOException{try(Workbook wb=WorkbookFactory.create(file.getInputStream())){Sheet sheet=wb.getSheetAt(0);Row header=sheet.getRow(sheet.getFirstRowNum());if(header==null)throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"The workbook is empty. Use the supplied guest list template.");Map<String,Integer> columns=new LinkedHashMap<>();for(int c=header.getFirstCellNum();c<header.getLastCellNum();c++)columns.put(cell(header,c).toLowerCase(),c);requireHeaders(columns.keySet());List<Map<String,String>> rows=new ArrayList<>();for(int r=sheet.getFirstRowNum()+1;r<=sheet.getLastRowNum();r++){Row current=sheet.getRow(r);if(current==null)continue;Map<String,String> row=new LinkedHashMap<>();for(String h:IMPORT_HEADERS)row.put(h,columns.containsKey(h)?cell(current,columns.get(h)):"");if(row.values().stream().allMatch(String::isBlank))continue;rows.add(row);}return rows;}}
 private static String cell(Row row,int index){Cell c=row.getCell(index);if(c==null)return "";DataFormatter formatter=new DataFormatter();return formatter.formatCellValue(c).trim();}
 private static void requireHeaders(Set<String> present){Set<String> normalised=new HashSet<>();for(String p:present)if(p!=null)normalised.add(p.trim().toLowerCase());List<String> missing=IMPORT_HEADERS.stream().filter(h->!normalised.contains(h)).toList();if(!missing.isEmpty())throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Missing column(s): "+String.join(", ",missing)+". Use the supplied guest list template headers: "+String.join(", ",IMPORT_HEADERS));}
 @PostMapping("/meetings/{id}/send-invites") public Object invite(@RequestHeader("Authorization")String h,@PathVariable Long id){User creator=auth(h);Meeting m=writable(creator,id);String sender=creator.phone!=null&&!creator.phone.isBlank()?creator.phone:defaultWhatsappSender;List<Invitation> issued=invitations.findByMeetingId(id);List<Map<String,Object>> out=new ArrayList<>();for(Guest g:guests.findByMeetingId(id)){Invitation i=issued.stream().filter(x->Objects.equals(x.guest.id,g.id)).findFirst().orElseGet(Invitation::new);i.meeting=m;i.guest=g;Map<String,String> links=dispatch(m,g,i,false);out.add(Map.of("guest",g.name,"rsvp_link",links.get("rsvp"),"personal_sign_in_link",links.get("sign_in"),"calendar_link",links.get("calendar"),"channel",i.channel,"status",i.deliveryStatus));}m.status="published";meetings.save(m);audit.record(creator.id,"send_invites","Meeting",m.id,"Dispatched "+out.size()+" invitation(s) for "+m.reference);return Map.of("sent",out.size(),"results",out,"whatsapp_sender",sender,"email_sender",defaultEmailSender,"qr_not_included",true);}
 @PostMapping("/meetings/{id}/reminders") public Object remind(@RequestHeader("Authorization")String h,@PathVariable Long id){User u=auth(h);Meeting m=writable(u,id);List<Invitation> issued=invitations.findByMeetingId(id);if(issued.isEmpty())throw new ResponseStatusException(HttpStatus.CONFLICT,"Send invitations before sending reminders");List<Map<String,Object>> out=new ArrayList<>();for(Invitation i:issued){if(i.response!=null)continue;Map<String,String> links=dispatch(m,i.guest,i,true);out.add(Map.of("guest",i.guest.name,"rsvp_link",links.get("rsvp"),"channel",i.channel,"reminders_sent",i.remindersSent));}audit.record(u.id,"send_reminders","Meeting",m.id,"Reminded "+out.size()+" non-responder(s) for "+m.reference);return Map.of("reminded",out.size(),"results",out);}
 /** Issues a fresh signed token for the invitation and delivers the invitation or reminder text. Any previously sent link for the guest stops working. */
 private Map<String,String> dispatch(Meeting m,Guest g,Invitation i,boolean reminder){String raw=newToken();i.tokenHash=hash(raw);i.deliveryStatus="sent";i.sentAt=OffsetDateTime.now();i.channel=g.phone!=null&&!g.phone.isBlank()?"whatsapp":"email";if(reminder){i.remindersSent++;i.lastReminderAt=OffsetDateTime.now();}String rsvp=baseUrl+"/rsvp.html?token="+raw,signIn=baseUrl+"/attendance.html?token="+raw,calendar=baseUrl+"/api/rsvp/"+raw+"/calendar.ics";String body=(reminder?"Reminder: ":"")+"BMC-MMS meeting: "+m.title+"\nDate: "+m.startAt+"\nLocation: "+Objects.toString(m.location,"")+"\nRSVP: "+rsvp+"\nPersonal Sign-In Link: "+signIn+"\nCalendar: "+calendar;if("whatsapp".equals(i.channel))notifications.whatsapp(g.phone,body);else notifications.email(g.email,(reminder?"BMC-MMS reminder: ":"BMC-MMS meeting invitation: ")+m.title,body);invitations.save(i);return Map.of("rsvp",rsvp,"sign_in",signIn,"calendar",calendar);}
 @GetMapping("/rsvp/{token}") public Object rsvpInfo(@PathVariable String token){Invitation i=invitations.findByTokenHash(hash(token)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invalid RSVP link"));Meeting m=i.meeting;return Map.of("meeting",Map.of("reference",m.reference,"title",m.title,"purpose",Objects.toString(m.purpose,""),"start_at",m.startAt,"end_at",m.endAt,"location",Objects.toString(m.location,""),"map_link",Objects.toString(m.mapLink,""),"virtual_link",Objects.toString(m.virtualLink,""),"status",m.status),"guest",Map.of("name",i.guest.name),"token",token);}
 @PostMapping("/rsvp/{token}") public Object rsvp(@PathVariable String token,@RequestBody RsvpIn x){if(!Set.of("confirmed","declined","tentative").contains(x.status()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Invalid RSVP status");if("declined".equals(x.status())&&(x.reason()==null||x.reason().isBlank()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"A decline reason is required");Invitation i=invitations.findByTokenHash(hash(token)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invalid RSVP link"));if("cancelled".equals(i.meeting.status))throw new ResponseStatusException(HttpStatus.CONFLICT,"This meeting has been cancelled");RsvpResponse r=i.response==null?new RsvpResponse():i.response;r.invitation=i;r.status=x.status();r.reason=x.reason();r.language=x.language()==null?"en":x.language();r.respondedAt=OffsetDateTime.now();i.response=r;invitations.save(i);audit.record(null,"rsvp","Invitation",i.id,i.guest.name+" responded "+r.status+" for meeting "+i.meeting.reference);String message="RSVP recorded";boolean leave=Objects.toString(x.reason(),"").toLowerCase().matches(".*(leave|likizo).*");return Map.of("status","saved","message",message,"hr_notice",leave?"Leave-related absence must still follow the official council HR leave procedure. This system does not process leave applications.":"");}
 @GetMapping("/meetings/{id}/attendance/qr") public Object attendanceQr(@RequestHeader("Authorization")String h,@PathVariable Long id){User u=auth(h);Meeting m=meetings.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Meeting not found"));if(!"admin".equals(u.role)&&!Objects.equals(m.createdBy,u.id))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only the Organizer may display the Session QR Code");if("cancelled".equals(m.status))throw new ResponseStatusException(HttpStatus.CONFLICT,"This meeting has been cancelled");OffsetDateTime now=OffsetDateTime.now(),from=m.startAt.minusMinutes(15),to=m.endAt.plusMinutes(15);if(now.isBefore(from)||now.isAfter(to))throw new ResponseStatusException(HttpStatus.CONFLICT,"Attendance QR is available only during the meeting window");String raw=newToken();QRSession q=new QRSession();q.meeting=m;q.sessionTokenHash=hash(raw);q.issuedAt=now;q.expiresAt=now.plusSeconds(qrRotationSeconds);qrSessions.save(q);String payload="{\"meetingId\":"+m.id+",\"sessionToken\":\""+raw+"\",\"expiresAt\":\""+q.expiresAt+"\"}";return Map.of("meeting_id",m.id,"payload",payload,"issued_at",q.issuedAt,"expires_at",q.expiresAt,"rotation_seconds",qrRotationSeconds);}
 @GetMapping("/attendance/{token}") public Object attendanceInfo(@PathVariable String token){Invitation i=invitations.findByTokenHash(hash(token)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Personal Sign-In Link expired"));AttendanceRecord a=attendance.findByMeetingIdAndParticipantId(i.meeting.id,i.guest.id).orElse(null);return Map.of("meeting",Map.of("reference",i.meeting.reference,"title",i.meeting.title,"start_at",i.meeting.startAt,"end_at",i.meeting.endAt,"location",Objects.toString(i.meeting.location,""),"status",i.meeting.status),"participant",i.guest.name,"attended",a!=null&&a.used,"signed_in_at",a!=null&&a.signedInAt!=null?a.signedInAt.toString():"");}
 @PostMapping("/attendance/sign-in") public Object attendanceSignIn(@RequestBody AttendanceIn x){Invitation i=invitations.findByTokenHash(hash(x.personal_token())).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Personal Sign-In Link expired"));AttendanceRecord existing=attendance.findByMeetingIdAndParticipantId(i.meeting.id,i.guest.id).orElse(null);if(existing!=null&&existing.used)throw new ResponseStatusException(HttpStatus.CONFLICT,"You are already marked as attended");Map<?,?> payload;try{payload=new com.fasterxml.jackson.databind.ObjectMapper().readValue(x.qr_payload(),Map.class);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invalid Session QR Code");}if(!Objects.equals(String.valueOf(payload.get("meetingId")),String.valueOf(i.meeting.id)))throw new ResponseStatusException(HttpStatus.CONFLICT,"Wrong meeting QR Code");String qr=String.valueOf(payload.get("sessionToken"));QRSession session=qrSessions.findBySessionTokenHash(hash(qr)).orElseThrow(()->new ResponseStatusException(HttpStatus.GONE,"QR expired — rescan the live Session QR Code"));if(!session.meeting.id.equals(i.meeting.id))throw new ResponseStatusException(HttpStatus.CONFLICT,"Wrong meeting QR Code");if(session.expiresAt.isBefore(OffsetDateTime.now()))throw new ResponseStatusException(HttpStatus.GONE,"QR expired — rescan the live Session QR Code");AttendanceRecord a=existing==null?new AttendanceRecord():existing;a.meeting=i.meeting;a.participantId=i.guest.id;a.personalTokenHash=hash(x.personal_token());a.signedInAt=OffsetDateTime.now();a.used=true;attendance.save(a);audit.record(null,"attendance_sign_in","Meeting",i.meeting.id,i.guest.name+" signed in at "+a.signedInAt);return Map.of("status","attended","signed_in_at",a.signedInAt,"message","Attendance recorded successfully");}
 @GetMapping(value="/rsvp/{token}/calendar.ics",produces="text/calendar") public ResponseEntity<String> calendar(@PathVariable String token){Invitation i=invitations.findByTokenHash(hash(token)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invalid RSVP link"));Meeting m=i.meeting;DateTimeFormatter f=DateTimeFormatter.ofPattern("yyyyMMdd'T'HHmmss'Z'");String body="BEGIN:VCALENDAR\r\nVERSION:2.0\r\nPRODID:-//Bukoba Municipal Council//Meetings//EN\r\nBEGIN:VEVENT\r\nUID:"+m.reference+"@bukobamc.go.tz\r\nDTSTAMP:"+OffsetDateTime.now(ZoneOffset.UTC).format(f)+"\r\nDTSTART:"+m.startAt.withOffsetSameInstant(ZoneOffset.UTC).format(f)+"\r\nDTEND:"+m.endAt.withOffsetSameInstant(ZoneOffset.UTC).format(f)+"\r\nSUMMARY:"+ics(m.title)+"\r\nDESCRIPTION:"+ics(Objects.toString(m.purpose,""))+"\r\nLOCATION:"+ics(Objects.toString(m.location,""))+"\r\nSTATUS:"+("cancelled".equals(m.status)?"CANCELLED":"CONFIRMED")+"\r\nEND:VEVENT\r\nEND:VCALENDAR\r\n";return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+m.reference+".ics").body(body);}
 private static String ics(String x){return Objects.toString(x,"").replace("\\","\\\\").replace(";","\\;").replace(",","\\,").replace("\n","\\n");}
 @GetMapping(value="/meetings/{id}/report.csv",produces="text/csv") public ResponseEntity<String> report(@RequestHeader("Authorization")String h,@PathVariable Long id){User u=auth(h);Meeting m=readable(u,id);List<Invitation> issued=invitations.findByMeetingId(id);Map<Long,AttendanceRecord> attended=new HashMap<>();for(AttendanceRecord a:attendance.findByMeetingId(id))attended.put(a.participantId,a);List<Guest> list=guests.findByMeetingId(id);Map<String,Integer> counts=new LinkedHashMap<>(Map.of("confirmed",0,"declined",0,"tentative",0,"no_response",0));int checkedIn=0;StringBuilder rows=new StringBuilder();for(Guest g:list){Invitation i=issued.stream().filter(x->Objects.equals(x.guest.id,g.id)).findFirst().orElse(null);String status=i!=null&&i.response!=null?i.response.status:"no_response";counts.put(status,counts.getOrDefault(status,0)+1);AttendanceRecord a=attended.get(g.id);boolean present=a!=null&&a.used;if(present)checkedIn++;rows.append(String.join(",",csv(g.name),csv(g.organization),csv(g.roleTitle),csv(g.phone),csv(g.email),csv(i==null?"":Objects.toString(i.channel,"")),csv(status),csv(i!=null&&i.response!=null?Objects.toString(i.response.reason,""):""),csv(i!=null&&i.response!=null&&i.response.respondedAt!=null?i.response.respondedAt.toString():""),csv(i==null?"not_invited":Objects.toString(i.deliveryStatus,"")),csv(present?"attended":"absent"),csv(present?a.signedInAt.toString():""))).append("\n");}StringBuilder csv=new StringBuilder();csv.append("Bukoba Municipal Council attendance report\n");csv.append("Meeting reference,").append(csv(m.reference)).append("\n");csv.append("Title,").append(csv(m.title)).append("\n");csv.append("Department,").append(csv(m.department)).append("\n");csv.append("Start,").append(csv(Objects.toString(m.startAt,""))).append("\n");csv.append("End,").append(csv(Objects.toString(m.endAt,""))).append("\n");csv.append("Venue,").append(csv(m.location)).append("\n");csv.append("Prepared by,").append(csv(u.name)).append("\n");csv.append("Generated at,").append(csv(OffsetDateTime.now().toString())).append("\n");csv.append("Invited,").append(list.size()).append("\n");csv.append("Confirmed,").append(counts.get("confirmed")).append("\n");csv.append("Declined,").append(counts.get("declined")).append("\n");csv.append("Tentative,").append(counts.get("tentative")).append("\n");csv.append("No response,").append(counts.get("no_response")).append("\n");csv.append("Checked in,").append(checkedIn).append("\n\n");csv.append("Name,Organisation,Role,Phone,Email,Channel,RSVP status,Reason,Response time,Delivery status,Check-in status,Check-in time\n").append(rows);audit.record(u.id,"export_report","Meeting",m.id,"Attendance report exported for "+m.reference);return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+m.reference+"-attendance.csv").body(csv.toString());}
 @GetMapping("/reports/summary") public Object summary(@RequestHeader("Authorization")String h){User u=auth(h);if(!"admin".equals(u.role))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only an administrator may view council-wide trends");List<Map<String,Object>> perMeeting=new ArrayList<>();int invited=0,confirmed=0,declined=0,tentative=0,noResponse=0,checkedIn=0;for(Meeting m:meetings.findAll()){List<Invitation> issued=invitations.findByMeetingId(m.id);int mc=0,md=0,mt=0,mn=0,ma=0;for(Invitation i:issued){String st=i.response==null?"no_response":i.response.status;if("confirmed".equals(st))mc++;else if("declined".equals(st))md++;else if("tentative".equals(st))mt++;else mn++;}for(AttendanceRecord a:attendance.findByMeetingId(m.id))if(a.used)ma++;int mi=(int)guests.countByMeetingId(m.id);invited+=mi;confirmed+=mc;declined+=md;tentative+=mt;noResponse+=mn+(mi-issued.size());checkedIn+=ma;Map<String,Object> row=new LinkedHashMap<>();row.put("id",m.id);row.put("reference",m.reference);row.put("title",m.title);row.put("department",Objects.toString(m.department,""));row.put("start_at",m.startAt);row.put("status",m.status);row.put("invited",mi);row.put("confirmed",mc);row.put("declined",md);row.put("tentative",mt);row.put("no_response",mn+(mi-issued.size()));row.put("checked_in",ma);perMeeting.add(row);}return Map.of("meetings",perMeeting.size(),"totals",Map.of("invited",invited,"confirmed",confirmed,"declined",declined,"tentative",tentative,"no_response",noResponse,"checked_in",checkedIn),"per_meeting",perMeeting);}
 @GetMapping("/meetings/{id}/audit") public Object meetingAudit(@RequestHeader("Authorization")String h,@PathVariable Long id){User u=auth(h);Meeting m=readable(u,id);return auditEntries.findByEntityAndEntityIdOrderByIdDesc("Meeting",m.id).stream().map(MeetingController::auditRow).toList();}
 @GetMapping("/audit") public Object auditTrail(@RequestHeader("Authorization")String h){User u=auth(h);if(!"admin".equals(u.role))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only an administrator may read the council audit trail");return auditEntries.findTop200ByOrderByIdDesc().stream().map(MeetingController::auditRow).toList();}
 private static Map<String,Object> auditRow(AuditLogEntry e){Map<String,Object> row=new LinkedHashMap<>();row.put("id",e.id);row.put("user_id",e.userId);row.put("action",e.action);row.put("entity",Objects.toString(e.entity,""));row.put("entity_id",e.entityId);row.put("detail",Objects.toString(e.detail,""));row.put("created_at",e.createdAt);return row;}
 private static String csv(String value){String x=Objects.toString(value,"").replace("\"","\"\"");return "\""+x+"\"";}
}
